const ws=figma.root.children.find(p=>p.name.startsWith("03"));await figma.setCurrentPageAsync(ws);
const out=[];
for(const f of ws.children){if(!/^\d\d_/.test(f.name))continue;
 const bad=f.children.filter(c=>c.layoutPositioning!=="ABSOLUTE"&&Math.round(c.width)!==375).map(c=>c.name+":"+Math.round(c.width));
 let rc=0;f.findAll(x=>x.reactions&&x.reactions.length).forEach(()=>rc++);
 out.push(f.name+" w"+f.width+" h"+Math.round(f.height)+" react"+rc+(bad.length?" BAD "+bad.join(","):""));}
return out.join("\n");

